 for key,label in [('prerequisite_fixes','Prerequisites'),('exact_stimulus','Exact stimulus'),('expected_observable_sequence','Expected sequence'),('case_binding','Additional binding'),('pass_conditions','PASS'),('hold_conditions','HOLD / failure boundary'),('cleanup_evidence','Cleanup evidence')]:
  md+='**'+label+'**\n\n'+''.join(f'- {v}\n' for v in r[key])+'\n'
 d=r['implementation_decision'];md+=f"**Implementation decision {'REQUIRED' if d['required'] else 'already owned; receiving evidence required'}:** {d['owner']} — {d['input']}\n\n**Preserved credit:** {r['historical_credit']}\n\n"
